import { Container, Sprite, Text } from 'pixi.js';

import { Device } from '@game-studio/device';
import { AssetManager } from '@game-studio/asset-manager';

import {
    CabinetUserPrefs,
    IAutoPlayDimensions,
    IAutoPlayText,
    ICabinetConfig,
    ICabinetInteractionMethods,
    ICabinetLayoutInfo,
    OneHandedPlaySetting,
    OneHandedPlaySettingStrings,
} from '../../types/cabinet';
import { autoPlayTextStyle } from '../../layout/text-style';

export class AutoPlayView extends Container {
    private device: Device;
    private interactionMethods: ICabinetInteractionMethods;
    private oneHandedSetting: OneHandedPlaySetting | OneHandedPlaySettingStrings;
    private layoutState: 'floating' | 'anchored' = 'floating';

    private maxLossText: Text;
    private changeStakeText: Text;
    private cancelText: Text;
    private confirmText: Text;
    private background: Sprite;
    private confirmButton: Sprite;
    private cancelButton: Sprite;

    // Layout Constants
    private static readonly TEXT_AREA_PERCENTAGE = 0.6;
    private static readonly BUTTON_AREA_PERCENTAGE = 0.4;
    private static readonly PADDING_PERCENTAGE = 0.05;
    private static readonly TEXT_GAP_PERCENTAGE = 0.2;

    // Scaling Constants
    private static readonly HOVER_SCALE_DOWN = 0.95;
    private static readonly HOVER_SCALE_UP = 1.05;
    private static readonly MAX_TEXT_SCALE = 0.7;
    private static readonly MAX_BUTTON_SCALE = 1.2;

    private correctButtonScale: number = 1;
    private isFloating: boolean = true;

    private get isMobilePortrait(): boolean {
        return this.device.type.isMobile && this.device.orientation.isPortrait;
    }
    private get isLeftHanded(): boolean {
        return !this.isDesktop && (this.oneHandedSetting === OneHandedPlaySetting.left || this.oneHandedSetting === OneHandedPlaySettingStrings.left);
    }
    private get isDesktop(): boolean {
        return this.device.type.isDesktop;
    }

    public set oneHandedPlaySetting(value: OneHandedPlaySetting | OneHandedPlaySettingStrings) {
        this.oneHandedSetting = value;

        this.positionComponents(this.background.width, this.background.height);
    }

    constructor(device: Device, interactionMethods: ICabinetInteractionMethods, userPrefs: CabinetUserPrefs) {
        super();

        this.device = device;
        this.interactionMethods = interactionMethods;
        this.oneHandedSetting = userPrefs.oneHandedPlay;

        this.createComponents();
        this.addButtonListeners();

        this.hide();
    }

    public show(): void {
        this.visible = true;
    }
    public hide(): void {
        this.visible = false;
    }

    public updateTextStyle(config: ICabinetConfig): void {
        autoPlayTextStyle.fill = config.text.message.colour;
        autoPlayTextStyle.fontFamily = config.text.message.font;
        autoPlayTextStyle.fontSize = config.text.message.fontSize;

        this.maxLossText.style = autoPlayTextStyle;
        this.changeStakeText.style = autoPlayTextStyle;
        this.cancelText.style = autoPlayTextStyle;
        this.confirmText.style = autoPlayTextStyle;
    }

    public setText(textSet: IAutoPlayText): void {
        this.maxLossText.text = textSet.maxLoss;
        this.changeStakeText.text = textSet.changeStake;
        this.cancelText.text = textSet.cancel;
        this.confirmText.text = textSet.confirm;
    }

    public onOrientationChange(cabinetLayoutInfo: ICabinetLayoutInfo, layoutState: 'floating' | 'anchored'): void {
        const dimensions = this.calculateDimensions(cabinetLayoutInfo);

        this.layoutState = layoutState;

        this.applyDimensions(dimensions);
    }

    public onLayoutChange(cabinetLayoutInfo: ICabinetLayoutInfo, layoutState: 'floating' | 'anchored'): void {
        const dimensions = this.calculateDimensions(cabinetLayoutInfo);

        this.layoutState = layoutState;

        this.applyDimensions(dimensions);
    }

    private calculateDimensions(cabinet: ICabinetLayoutInfo): IAutoPlayDimensions {
        const cabinetX = cabinet.position.x;
        const cabinetY = cabinet.position.y;
        const isLeftHanded = !this.isDesktop && this.oneHandedSetting === OneHandedPlaySetting.left;

        if (this.layoutState === 'floating') {
            const autoplayWidth = cabinet.backgroundWidth;
            const autoplayHeight = cabinet.backgroundHeight * 0.8;
            const gap = autoplayHeight * 0.1; // 10% gap between popup and action button

            const autoplayX = cabinetX;
            const autoplayY = cabinet.dimensionsY - gap - autoplayHeight;

            return { width: autoplayWidth, height: autoplayHeight, x: autoplayX, y: autoplayY, isFloating: true };
        }

        const cabinetHeight = cabinet.height;

        // Select the appropriate stake button and calculate its edge position
        const stakeButton = isLeftHanded ? cabinet.increaseStakeButton : cabinet.decreaseStakeButton;
        const buttonEdge = stakeButton.x + stakeButton.width * 0.5 * (isLeftHanded ? -1 : 1);

        const autoplayWidth = isLeftHanded ? cabinet.backgroundWidth - buttonEdge : buttonEdge;
        const autoplayX = isLeftHanded ? cabinetX + buttonEdge : cabinetX;
        const autoplayHeight = cabinetHeight * 0.8;
        const autoplayY = cabinetY - autoplayHeight * 1.2; // 20% Gap Between Cabinet and AutoPlay Popup

        return { width: autoplayWidth, height: autoplayHeight, x: autoplayX, y: autoplayY, isFloating: false };
    }

    private applyDimensions(dimensions: IAutoPlayDimensions): void {
        this.isFloating = dimensions.isFloating;

        this.background.width = dimensions.width;
        this.background.height = dimensions.height;
        this.position.set(dimensions.x, dimensions.y);

        this.positionComponents(dimensions.width, dimensions.height);
    }

    private createComponents(): void {
        this.createBackground();
        this.createTexts();
        this.createButtons();
    }

    private createBackground(): void {
        this.background = new Sprite(AssetManager.getTexture('autoplay-background'));

        this.addChild(this.background);
    }

    private createTexts(): void {
        // Main text elements
        this.maxLossText = new Text('', autoPlayTextStyle);
        this.changeStakeText = new Text('', autoPlayTextStyle);

        this.maxLossText.name = 'max-loss-text';
        this.changeStakeText.name = 'change-stake-text';

        this.addChild(this.maxLossText, this.changeStakeText);

        // Button text elements
        this.cancelText = new Text('', autoPlayTextStyle);
        this.confirmText = new Text('', autoPlayTextStyle);

        this.cancelText.name = 'cancel-text';
        this.confirmText.name = 'confirm-text';

        this.cancelText.anchor.set(0.5);
        this.confirmText.anchor.set(0.5);
    }

    private createButtons(): void {
        this.confirmButton = new Sprite(AssetManager.getTexture('autoplay-confirm-button'));
        this.cancelButton = new Sprite(AssetManager.getTexture('autoplay-cancel-button'));

        [this.cancelButton, this.confirmButton].forEach((button) => {
            button.anchor.set(0.5);
            button.interactive = true;
            button.cursor = 'pointer';
        });

        this.confirmButton.addChild(this.confirmText);
        this.cancelButton.addChild(this.cancelText);

        this.confirmButton.name = 'confirm-button';
        this.cancelButton.name = 'cancel-button';

        this.addChild(this.confirmButton, this.cancelButton);
    }

    private addButtonListeners(): void {
        this.setupButtonEvents(this.cancelButton, () => this.onCancelClick());
        this.setupButtonEvents(this.confirmButton, () => this.onConfirmClick());
    }

    private setupButtonEvents(button: Sprite, onClickCallback: () => void): void {
        button.on('pointertap', onClickCallback, this);
        button.on('pointerdown', () => button.scale.set(this.correctButtonScale * AutoPlayView.HOVER_SCALE_DOWN));
        button.on('pointerup', () => button.scale.set(this.correctButtonScale));
        button.on('pointerover', () => button.scale.set(this.correctButtonScale * AutoPlayView.HOVER_SCALE_UP));
        button.on('pointerout', () => button.scale.set(this.correctButtonScale));
        button.on('pointercancel', () => button.scale.set(this.correctButtonScale));
    }

    private positionComponents(width: number, height: number): void {
        const textAreaWidth = width * AutoPlayView.TEXT_AREA_PERCENTAGE;
        const buttonAreaWidth = width * AutoPlayView.BUTTON_AREA_PERCENTAGE;

        const textAreaLeft = this.isLeftHanded ? width - textAreaWidth : 0;
        const buttonAreaLeft = this.isLeftHanded ? 0 : textAreaWidth;

        this.positionText(textAreaWidth, height, textAreaLeft);
        this.positionButtons(buttonAreaWidth, height, buttonAreaLeft);
    }

    private positionText(areaWidth: number, height: number, leftEdge: number): void {
        const padding = areaWidth * AutoPlayView.PADDING_PERCENTAGE;
        const centerY = height * 0.5;
        const verticalTextGap = height * AutoPlayView.TEXT_GAP_PERCENTAGE;

        if (this.isLeftHanded) {
            const textRight = leftEdge + areaWidth - padding;
            this.maxLossText.anchor.set(1, 0.5);
            this.maxLossText.position.set(textRight, centerY - verticalTextGap);

            this.changeStakeText.anchor.set(1, 0.5);
            this.changeStakeText.position.set(textRight, centerY + verticalTextGap);
        } else {
            const textLeft = leftEdge + padding;
            this.maxLossText.anchor.set(0, 0.5);
            this.maxLossText.position.set(textLeft, centerY - verticalTextGap);

            this.changeStakeText.anchor.set(0, 0.5);
            this.changeStakeText.position.set(textLeft, centerY + verticalTextGap);
        }

        // Scale texts
        this.resizeMainTexts(areaWidth * 0.9, height);
    }

    private positionButtons(areaWidth: number, height: number, leftEdge: number): void {
        const padding = areaWidth * AutoPlayView.PADDING_PERCENTAGE;
        const availableWidth = areaWidth - padding * 2;
        const centerX = leftEdge + areaWidth * 0.5;
        const centerY = height * 0.5;

        if (this.isMobilePortrait && !this.isFloating) {
            this.positionButtonsVertically(centerX, centerY, availableWidth, height);
        } else {
            this.positionButtonsHorizontally(centerX, centerY, availableWidth, height);
        }

        this.resizeButtonText();
    }

    private positionButtonsVertically(centerX: number, centerY: number, width: number, height: number): void {
        const verticalSpacing = height * 0.05;
        const buttonHeight = (height * 0.9 - verticalSpacing) * 0.5;

        this.confirmButton.position.set(centerX, centerY - verticalSpacing * 0.5 - buttonHeight * 0.5);
        this.cancelButton.position.set(centerX, centerY + verticalSpacing * 0.5 + buttonHeight * 0.5);

        this.resizeButtons(width, buttonHeight);
    }

    private positionButtonsHorizontally(centerX: number, centerY: number, width: number, height: number): void {
        const horizontalSpacing = width * 0.05;
        const buttonWidth = (width - horizontalSpacing) * 0.5;
        const buttonHeight = height * 0.85;

        this.cancelButton.position.set(centerX - buttonWidth * 0.5 - horizontalSpacing * 0.5, centerY);
        this.confirmButton.position.set(centerX + buttonWidth * 0.5 + horizontalSpacing * 0.5, centerY);

        this.resizeButtons(buttonWidth, buttonHeight);
    }

    private resizeMainTexts(maxWidth: number, totalHeight: number): void {
        [this.maxLossText, this.changeStakeText].forEach((text) => {
            if (!text.text) {
                return;
            }

            text.scale.set(1);

            const maxHeight = totalHeight * 0.4;
            const widthScale = maxWidth / text.width;
            const heightScale = maxHeight / text.height;
            const scale = Math.min(widthScale, heightScale, AutoPlayView.MAX_TEXT_SCALE);

            text.scale.set(scale);
        });
    }

    private resizeButtons(maxWidth: number, maxHeight: number): void {
        const buttons = [this.confirmButton, this.cancelButton];

        buttons.forEach((button) => button.scale.set(1));

        const scales = buttons.map((button) => {
            const widthScale = maxWidth / button.width;
            const heightScale = maxHeight / button.height;

            return Math.min(widthScale, heightScale, AutoPlayView.MAX_BUTTON_SCALE);
        });

        this.correctButtonScale = Math.min(...scales);

        buttons.forEach((button) => button.scale.set(this.correctButtonScale));
    }

    private resizeButtonText(): void {
        const texts = [this.cancelText, this.confirmText];
        const buttons = [this.cancelButton, this.confirmButton];

        const scales = texts.map((text, index) => {
            if (!text.text) {
                return 1;
            }

            text.scale.set(1);

            const button = buttons[index];
            const availableWidth = button.texture.width * 0.9;
            const availableHeight = button.texture.height * 0.8;
            const widthScale = availableWidth / text.width;
            const heightScale = availableHeight / text.height;

            return Math.min(widthScale, heightScale);
        });

        const uniformScale = Math.min(...scales);

        texts.forEach((text) => text.scale.set(uniformScale));
    }

    private onCancelClick(): void {
        this.interactionMethods.onAutoPlayCancelClick();
        this.hide();
    }

    private onConfirmClick(): void {
        this.interactionMethods.onAutoPlayConfirmClick();
        this.hide();
    }
}
